mapper.select:
SELECT a.SEC_ID AS secId, /**债券代码**/ b.FINPROD_ID AS finprodId, /**资产代码(金融产品代码)**/ b.FINPROD_ABBR AS finprodAbbr, /**债券简称(金融产品简称)**/ a.VALUE_SOURCE AS valueSource, /**估值来源**/ a.VALUE_DATE AS valueDate, /**估值日**/ a.LAST_PERIOD AS lastPeriod, /**剩余期限**/ a.PRICE AS price, /**市价全价**/ a.NETPRICE AS netprice, /**市价净价**/ a.M_DURATION AS mDuration, /**市价久期**/ a.M_CONVEXITY AS mConvexity, /**市价凸性**/ a.BPVALUE AS bpvalue, /**基点价值**/ a.SDURATION AS sduration, /**利差久期**/ a.SCNVXTY AS scnvxty, /**利差凸性**/ a.INTEREST_DURATION AS interestDuration, /**利率久期**/ a.INTEREST_CNVXTY AS interestCnvxty, /**利率凸性**/ a.BPYIELD AS bpyield /**市价收益率**/ FROM mst_BOND_VALUATION_INFO a INNER JOIN FIN_PRODUCT b ON a.SEC_ID = b.FINPROD_MARKET_ID WHERE 1=1
AND b.FINPROD_TYPE = #{finprodType}
AND b.FINPROD_ID LIKE concat_ws('','%' , #{finprodId} , '%')
AND b.FINPROD_ABBR LIKE concat_ws('','%' ,#{finprodAbbr} , '%')
AND a.VALUE_SOURCE = #{valueSource}
AND a.VALUE_DATE >= #{valueDateBegin}
AND a.VALUE_DATE <= #{valueDateEnd}
